language plpgsql as $fn$
declare
    v_final constant text[] := array['locked', 'paid', 'posted', 'closed'];
    v_free constant text[] := array['run_status', 'updated_at', 'updated_by', 'row_version'];
    v_old_run uuid;
    v_new_run uuid;
