begin
    if tg_op <> 'INSERT' then
        v_old_run := case when tg_table_name in ('pay_results', 'pay_run_employees') then (to_jsonb(old) ->> 'pay_run_id')::uuid
                          else (select r.pay_run_id from hrm.pay_results r where r.id = (to_jsonb(old) ->> 'result_id')::uuid) end;
    end if;
    if tg_op <> 'DELETE' then
        v_new_run := case when tg_table_name in ('pay_results', 'pay_run_employees') then (to_jsonb(new) ->> 'pay_run_id')::uuid
                          else (select r.pay_run_id from hrm.pay_results r where r.id = (to_jsonb(new) ->> 'result_id')::uuid) end;
    end if;
    if v_old_run is not null then
        select status into v_status from hrm.pay_runs where id = v_old_run for share;
        if v_status = any (v_final) and not (tg_op = 'UPDATE' and tg_table_name = 'pay_run_employees'
                                           and v_new_run = v_old_run and (to_jsonb(new) - v_free) = (to_jsonb(old) - v_free)) then
            raise exception '%: the results of locked pay run % never change (FR-XM-05, PAY-33); correct them in a later run', tg_table_name, v_old_run
                using errcode = '23514', constraint = 'ck_pay_run_locked';
        end if;
    end if;
    if v_new_run is not null and v_new_run is distinct from v_old_run then
        select status into v_status from hrm.pay_runs where id = v_new_run for share;
        if v_status = any (v_final) then
            raise exception '%: pay run % is locked and takes no new results (FR-XM-05, PAY-33); correct them in a later run', tg_table_name, v_new_run
                using errcode = '23514', constraint = 'ck_pay_run_locked';
        end if;
    end if;
    return case when tg_op = 'DELETE' then old else new end;
end
