-- hrm.pay_runs: Lock: trigger refuses UPDATE and DELETE once the parent pay run status is locked or later (FR-XM-05, PAY-33); status column may still advance (paid, posted, closed) through the run service only.
drop function if exists hrm.todo_pay_runs_lock();
create or replace function hrm.tg_pay_runs_lock() returns trigger
language plpgsql as $fn$
declare
    v_final constant text[] := array['locked', 'paid', 'posted', 'closed'];
    v_free constant text[] := array['status', 'stage_log', 'updated_at', 'updated_by', 'row_version'];
begin
    if not (old.status = any (v_final)) then
        return case when tg_op = 'DELETE' then old else new end;
    end if;
    if tg_op = 'DELETE' then
        raise exception 'pay run %: a locked run is never deleted (FR-XM-05)', old.id
            using errcode = '23514', constraint = 'ck_pay_run_locked';
    end if;
    if not (new.status = any (v_final)) or array_position(v_final, new.status) < array_position(v_final, old.status)
       or (to_jsonb(new) - v_free) is distinct from (to_jsonb(old) - v_free) then
        raise exception 'pay run %: a locked run only moves forward through paid, posted and closed (FR-XM-05, PAY-33)', old.id
            using errcode = '23514', constraint = 'ck_pay_run_locked';
    end if;
    return new;
end
